106: pub fn parse_mask(mask: &str, custom_charsets: &CustomCharsets) -> Result<ParsedMask, FinderError> {
107:     let mut positions = Vec::new();
108:     let mut chars = mask.chars();
109: 
110:     while let Some(c) = chars.next() {
111:         if c == '?' {
112:             match chars.next() {
113:                 Some('?') => positions.push(vec!['?']),
114:                 Some(token @ '1'..='4') => {
115:                     let idx = (token as usize) - ('1' as usize);
116:                     match &custom_charsets[idx] {
117:                         Some(charset) => positions.push(charset.clone()),
118:                         None => {
119:                             return Err(CliArgumentError {
120:                                 message: format!(
121:                                     "Custom charset ?{token} used in mask but --customCharset{token} not provided"
122:                                 ),
123:                             });
124:                         }
125:                     }
126:                 }
127:                 Some(token) => {
128:                     if let Some(builtin) = resolve_builtin_token(token) {
129:                         positions.push(builtin);
130:                     } else {
131:                         return Err(CliArgumentError {
132:                             message: format!("Unknown mask token '?{token}'"),
133:                         });
134:                     }
135:                 }
136:                 None => {
137:                     return Err(CliArgumentError {
138:                         message: "Mask ends with incomplete token '?'".to_string(),
139:                     });
140:                 }
141:             }
142:         } else {
143:             positions.push(vec![c]);
144:         }
145:     }
146: 
147:     if positions.is_empty() {
148:         return Err(CliArgumentError {
149:             message: "Mask pattern is empty".to_string(),
150:         });
151:     }
152: 
153:     Ok(ParsedMask { positions })
154: }
155: 
156: /// Compute the total number of passwords for a parsed mask.
157: pub fn mask_password_count(mask: &ParsedMask) -> usize {
158:     mask.positions.iter().map(|p| p.len()).product()
159: }
160: 
161: struct MaskPasswordGenerator {
162:     positions: Vec<Vec<u8>>,
163:     indices: Vec<usize>,
164:     total: usize,
165:     generated: usize,
166:     finished: bool,
167: }
168: 
169: impl MaskPasswordGenerator {
170:     fn new(mask: ParsedMask) -> Self {
171:         let total = mask_password_count(&mask);
172:         let len = mask.positions.len();
173:         // Convert char positions to u8 once at construction
174:         let positions = mask
175:             .positions
176:             .into_iter()
177:             .map(|chars| chars.into_iter().map(|c| c as u8).collect())
178:             .collect();
179:         Self {
180:             positions,
181:             indices: vec![0; len],
182:             total,
183:             generated: 0,
184:             finished: total == 0,
185:         }
186:     }
187: 
188:     fn current_password(&self) -> Vec<u8> {
189:         self.indices
190:             .iter()
191:             .enumerate()
192:             .map(|(pos, &idx)| self.positions[pos][idx])
193:             .collect()
194:     }
195: }
196: 
197: impl Iterator for MaskPasswordGenerator {
198:     type Item = Vec<u8>;
199: 
200:     fn next(&mut self) -> Option<Self::Item> {
201:         if self.finished {
202:             return None;
203:         }
204: 
205:         let password = self.current_password();
206:         self.generated += 1;
207: 
208:         if self.generated == self.total {
209:             self.finished = true;
210:         } else {
211:             // Increment: rightmost position first (odometer style)
212:             let mut carry = true;
213:             for i in (0..self.indices.len()).rev() {
214:                 if carry {
215:                     self.indices[i] += 1;
216:                     if self.indices[i] >= self.positions[i].len() {
217:                         self.indices[i] = 0;
218:                     } else {
219:                         carry = false;
220:                     }
221:                 }
222:             }
223:         }
224: 
225:         Some(password)

